#!/usr/bin/env bash
# Generated by pipeline_compiler. nvinfer_backport must be on the GStreamer
# plugin path (verify: gst-inspect-1.0 nvinfer_backport). Override CAM /
# CAM_W / CAM_H / CAM_FPS / CAM_FMT via env to match your camera's
# supported capture modes (`v4l2-ctl --list-formats-ext -d <device>`).
set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

CAM="${CAM:-/dev/video0}"
CAM_W=${CAM_W:-1920}
CAM_H=${CAM_H:-1080}
CAM_FPS=${CAM_FPS:-30}
CAM_FMT="${CAM_FMT:-YUYV}"

# ── v4l2 caps-probe (adapts to the attached camera; CAM_PROBE=0 skips) ──
if [ "${CAM_PROBE:-1}" = "1" ] && command -v v4l2-ctl >/dev/null 2>&1; then
  _v4l2_modes="$(v4l2-ctl --list-formats-ext -d "$CAM" 2>/dev/null || true)"
  _v4l2_pick="$(printf '%s\n' "$_v4l2_modes" | awk -v rw="$CAM_W" -v rh="$CAM_H" '
    function emit() {
      if (fmt=="" || w=="") return
      rank=(fmt=="MJPG"?0:(fmt=="YUYV"||fmt=="YUY2"?1:2))
      area=w*h; da=(area>rw*rh)?area-rw*rh:rw*rh-area
      if (best=="" || rank<brank || (rank==brank && (cf>bfps || (cf==bfps && da<bda)))) {
        best=fmt" "w" "h" "cf; brank=rank; bfps=cf; bda=da
      }
    }
    /^[[:space:]]*\[[0-9]+\]:[[:space:]]*.[A-Z0-9]+./ {
      f=$0; sub(/^[^A-Z0-9]*\[[0-9]+\]:[[:space:]]*./,"",f); sub(/[^A-Z0-9].*$/,"",f); fmt=f; next
    }
    /Size: Discrete/ { split($NF,a,"x"); w=a[1]; h=a[2]; next }
    /Interval: Discrete/ { cf=$0; sub(/.*\(/,"",cf); sub(/[^0-9.].*$/,"",cf); cf=cf+0; emit() }
    END { print best }')"
  if [ -n "$_v4l2_pick" ]; then
    CAM_FMT="${_v4l2_pick%% *}"; _rest="${_v4l2_pick#* }"
    CAM_W="${_rest%% *}"; _rest="${_rest#* }"
    CAM_H="${_rest%% *}"; CAM_FPS="${_rest##* }"
    echo "[run.sh] v4l2 probe selected: $CAM_FMT ${CAM_W}x${CAM_H}@${CAM_FPS}fps on $CAM" >&2
  fi
fi
# Derive caps + decoder from the (probed) format: MJPG → jpegdec, else raw YUY2.
if [ "$CAM_FMT" = "MJPG" ]; then
  SRC_CAPS="image/jpeg,width=${CAM_W},height=${CAM_H},framerate=${CAM_FPS}/1"; DECODE="jpegdec ! "
else
  SRC_CAPS="video/x-raw,format=YUY2,width=${CAM_W},height=${CAM_H},framerate=${CAM_FPS}/1"; DECODE=""
fi

if [ -f "${DIR}/parsers/Makefile" ] && command -v make >/dev/null 2>&1; then
  make -C "${DIR}/parsers" || { echo "parser/.so build failed" >&2; exit 1; }
fi

timeout --signal=INT --kill-after=2s 5s gst-launch-1.0 -e nvstreammux name=mux batch-size=1 width=1280 height=720 batched-push-timeout=40000 live-source=1 v4l2src device="${CAM}" ! ${SRC_CAPS} ! ${DECODE}videoconvert ! nvvideoconvert ! "video/x-raw(memory:NVMM),format=NV12" ! mux.sink_0 mux. ! queue max-size-buffers=4 ! nvvideoconvert ! nvinfer_backport config-file-path="${DIR}/configs/config_det_pgie.txt" ! queue max-size-buffers=4 ! nvinfer_backport config-file-path="${DIR}/configs/config_pose_other.txt" ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libpose_render_process.so" process-func-name=NvDsCustomPostProcess ! queue max-size-buffers=4 ! nvdsosd ! queue max-size-buffers=4 ! nvmultistreamtiler rows=1 columns=1 width=1280 height=720 ! nvvideoconvert ! fpsdisplaysink video-sink=nveglglessink sync=1
